    private void isRawat() {
        try {
            ps=koneksi.prepareStatement(
                    "select reg_periksa.no_rkm_medis,pasien.nm_pasien, if(pasien.jk='L','Laki-Laki','Perempuan') as jk,pasien.tgl_lahir,reg_periksa.tgl_registrasi "+
                    "from reg_periksa inner join pasien on reg_periksa.no_rkm_medis=pasien.no_rkm_medis "+
                    "where reg_periksa.no_rawat=?");
            try {
                ps.setString(1,TNoRw.getText());
                rs=ps.executeQuery();
                if(rs.next()){
                    TNoRM.setText(rs.getString("no_rkm_medis"));
                    DTPCari1.setDate(rs.getDate("tgl_registrasi"));
                    TPasien.setText(rs.getString("nm_pasien"));
                    Jk.setText(rs.getString("jk"));
                    TglLahir.setText(rs.getString("tgl_lahir"));
                    TD.setText(Sequel.cariIsi("select tensi from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    Nadi.setText(Sequel.cariIsi("select nadi from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    RR.setText(Sequel.cariIsi("select respirasi from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    Suhu.setText(Sequel.cariIsi("select suhu_tubuh from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    GCS.setText(Sequel.cariIsi("select gcs from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    BB.setText(Sequel.cariIsi("select berat from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    //TB.setText(Sequel.cariIsi("select tinggi from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    //SPO.setText(Sequel.cariIsi("select spo2 from pemeriksaan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    RPS.setText("-");
                    KeluhanUtama.setText(Sequel.cariIsi("select keluhan_utama from penilaian_awal_keperawatan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    RPD.setText(Sequel.cariIsi("select rpd from penilaian_awal_keperawatan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    //RPK.setText(Sequel.cariIsi("select rpk from penilaian_awal_keperawatan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    RPO.setText(Sequel.cariIsi("select rpo from penilaian_awal_keperawatan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    Alergi.setText(Sequel.cariIsi("select alergi from penilaian_awal_keperawatan_ralan where no_rawat='"+TNoRw.getText()+"'"));
                    //Penunjang.setText(Sequel.cariIsi("select group_concat(jns_perawatan_lab.nm_perawatan) as nama from permintaan_pemeriksaan_lab inner join jns_perawatan_lab on permintaan_pemeriksaan_lab.kd_jenis_prw=jns_perawatan_lab.kd_jenis_prw inner join permintaan_lab on permintaan_lab.noorder=permintaan_pemeriksaan_lab.noorder where permintaan_lab.no_rawat='"+TNoRw.getText()+"'"));
                    Lab.setText("Laboratorium : "+Sequel.cariIsi("select group_concat(jns_perawatan_lab.nm_perawatan) as nama from permintaan_pemeriksaan_lab inner join jns_perawatan_lab on permintaan_pemeriksaan_lab.kd_jenis_prw=jns_perawatan_lab.kd_jenis_prw inner join permintaan_lab on permintaan_lab.noorder=permintaan_pemeriksaan_lab.noorder where permintaan_lab.no_rawat='"+TNoRw.getText()+"'"));
                    Rad.setText("Radiologi : "+Sequel.cariIsi("select group_concat(jns_perawatan_radiologi.nm_perawatan) as nama from permintaan_pemeriksaan_radiologi inner join jns_perawatan_radiologi on permintaan_pemeriksaan_radiologi.kd_jenis_prw=jns_perawatan_radiologi.kd_jenis_prw inner join permintaan_radiologi on permintaan_radiologi.noorder=permintaan_pemeriksaan_radiologi.noorder where permintaan_radiologi.no_rawat='"+TNoRw.getText()+"'"));
                    Terapi.setText(Sequel.cariIsi("select group_concat(databarang.nama_brng,' ',resep_dokter.jml,'(',databarang.kode_sat,')',' ',resep_dokter.aturan_pakai) as nama from resep_dokter inner join databarang on resep_dokter.kode_brng=databarang.kode_brng inner join resep_obat on resep_obat.no_resep=resep_dokter.no_resep where resep_obat.no_rawat='"+TNoRw.getText()+"'"));
                }
            } catch (Exception e) {
                System.out.println("Notif : "+e);
            } finally{
                if(rs!=null){
                    rs.close();
                }
                if(ps!=null){
                    ps.close();
                }
            }
        } catch (Exception e) {
            System.out.println("Notif : "+e);
        }
        tampilPerawatan();
    }
 
